    if not isinstance(entry.previous_hash, (bytes, bytearray)):
        raise TypeError("entry.previous_hash must be bytes")
    if not isinstance(entry.entry_hash, (bytes, bytearray)):
        raise TypeError("entry.entry_hash must be bytes")
