    digest_size = _digest_size(hash_name)
    previous_hash = bytes(entry.previous_hash)
    if len(previous_hash) != digest_size:
        raise ValueError(f"entry.previous_hash must be {digest_size} bytes")
    expected_hash = entry_digest(
        entry.index,
        previous_hash,
        bytes(entry.payload),
        hash_name=hash_name,
